class UnitController:
    def __init__(self, authz):
        self.authz = authz
        self.state = 'READY'
        self.trip_active = False

    def trip(self):
        self.trip_active = True
        self.state = 'FAULT'

    def handle(self, principal, command):
        op = command.get('op')
        if not self.authz.allowed(principal, op):
            raise PermissionError(op)
        if op == 'start':
            return self._start()
        if op == 'reset':
            return self._reset()
        raise ValueError('unsupported command')

    def _start(self):
        if self.state != 'READY':
            raise RuntimeError('invalid state')
        self.state = 'RUNNING'
        return self.state

    def _reset(self):
        if self.state != 'FAULT':
            raise RuntimeError('reset requires FAULT')
        self.state = 'READY'
        if self.trip_active:
            raise RuntimeError('trip is still active')
        self.trip_active = False
        return self.state

class Controller:
    def __init__(self, authz):
        self.authz = authz
        self.state = 'READY'
        self.target = 0.0

    def trip(self):
        self.state = 'FAULT'

    def handle(self, principal, command):
        op = command.get('op')
        if op in {'start', 'stop'}:
            if not self.authz.allowed(principal, op):
                raise PermissionError(op)
            return self._apply(op, command)
        if op == 'set_target':
            return self._apply(op, command)
        raise ValueError('unsupported command')

    def _apply(self, op, command):
        if op == 'start':
            if self.state != 'READY':
                raise RuntimeError('invalid state')
            self.state = 'RUNNING'
        elif op == 'stop':
            self.state = 'STOPPED'
        elif op == 'set_target':
            self.target = float(command['value'])
        return self.state, self.target

class ModeController:
    def __init__(self):
        self.state = 'READY'
        self.mode = 'LOCAL'

    def handle(self, principal, command):
        op = command.get('op')
        claimed_role = command.get('role')
        if op in {'start', 'stop', 'set_mode'}:
            if claimed_role not in {'operator', 'maintainer'}:
                raise PermissionError('role not permitted')
            return self._execute(op, command)
        raise ValueError('unsupported command')

    def _execute(self, op, command):
        if op == 'start':
            if self.state != 'READY':
                raise RuntimeError('invalid state')
            self.state = 'RUNNING'
        elif op == 'stop':
            self.state = 'STOPPED'
        elif op == 'set_mode':
            self.mode = command['mode']
        return self.state, self.mode
